--region public
function CardProgressionEquipmentScoreDetailNode:RefreshUI(equipDojo)
    if not equipDojo then return end
    
    self:RefreshEvaluateScore(equipDojo)
    self:RefreshMainAttrEvaluateScore(equipDojo)
    self:RefreshSubAttrEvaluateScore(equipDojo)
    self:RefreshLadderRiseAttributesScore(equipDojo)
end
