---刷新装备评分
function CardProgressionEquipmentScoreDetailNode:RefreshEvaluateScore(equipDojo)
    local score = equipComp:CalculateEvaluateScore(equipDojo)
    CfUtils.FillText(self.TxtNumber, score)
    local rankConf = CfUtils.GetCf(AutoIds.IdSetting6124, "EquipmentScoreRankVo", true)
    for _, v in ipairs(checkTable(rankConf)) do
        if score >= checkInt(v.rankScoremin) and score <= checkInt(v.rankScoremax) then
            -- CfUtils.SetUISwitchImage(self.ImgScore1, v.rank)
            -- CfUtils.SetUISwitchImage(self.ImgScore2, v.rank)
            local rank = v.rank
            local conf = CardProgressionConstants.EquipScoreRankConf[rank]
            if conf then
                local path, colorString = SafeUnpack(conf)
                local color = XLuaUtils.HexToColor(colorString)
                self.ImgScore1.color = color
                self.ImgScore2:LoadSprite(path)
                self.ImgScore2:SetColor(color)
            end
            break
        end
    end
end

---刷新主属性评分
function CardProgressionEquipmentScoreDetailNode:RefreshMainAttrEvaluateScore(equipDojo)
    local score = equipComp:CalculateMainAttrEvaluateScore(equipDojo)
    CfUtils.FillText(self.MainTxtNumber, score)
end

---刷新副属性评分
function CardProgressionEquipmentScoreDetailNode:RefreshSubAttrEvaluateScore(equipDojo)
    if checkInt(equipDojo.star) == 0 then
        CfUtils.SetActive(self.OtherAttributes, false)
        return
    else
        CfUtils.SetActive(self.OtherAttributes, true)
    end
    
    local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
    for i = 1, CardProgressionConstants.EquipmentSubAttrLimit do
        local node = self.OtherAttributes:Find(string.format("AttributeNode%d", i))
        if node then
            if checkInt(equipDojo.star) >= i then
                CfUtils.SetActive(node, true)
                local txtNode = node:Find('TxtNumber')
                local attrId  = equipDojo[string.format('attr%dId', i)]
                local num  = equipDojo[string.format('attr%dNum', i)]
                local quality  = equipDojo[string.format('attr%dQuality', i)]
                local score = equipComp:CalculateSubAttrEvaluateScore(equipVo, attrId, num, quality)
                CfUtils.FillText(txtNode, '+' .. score)
            else
                CfUtils.SetActive(node, false)
            end
        end
    end
end

---@param equipDojo EquipDojo
function CardProgressionEquipmentScoreDetailNode:RefreshLadderRiseAttributesScore(equipDojo)
    local isShow = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id118) and EquipUtils.IsUnlockLadderRiseAttr(equipDojo)
    SetActive(self.LadderRiseAttributes, isShow)
    if isShow then
        local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
        local attrs = equipDojo:GetLadderRiseAttrs()
        for index, attr in ipairs(attrs) do
            local node = self.LadderRiseAttributes:Find(string.format("AttributeNode%d", index))
            SetActive(node, attr.isUnlock)
            if attr.isUnlock then
                local score = equipComp:CalculateLadderAttrEvaluateScore(index, equipVo, attr)
                local txtNode = node:Find('TxtNumber')
                CfUtils.FillText(txtNode, '+' .. score)
            end
        end
        
    end
end

